import json,pathlib,hashlib,subprocess
root=pathlib.Path(__file__).resolve().parents[2];out=root/'汇报PPT';core=root/'EDA/code_3DIC EDA'
d=json.loads((out/'assets/data_verified.json').read_text(encoding='utf8'))
def ref(model,c,v):
 a=d['reference'][f'{model}/open_3d_{c}/{c}_{v}']; r=next(x for p,x in a.items() if p.endswith('reference_report.json')); i=next(x for p,x in a.items() if p.endswith('invocation.json'))
 return r,i
rows=[];checks=[]
for model in ['reference_20261029','reference_20261103']:
 for c in ['case001','case003','case005']:
  identities=[]
  for v in ['v3_1','v3_2','v3_3','v3_4','v3_5','v3_6','v4','v4_2']:
   key=f'{model}/open_3d_{c}/{c}_{v}'
   if key not in d['reference']:continue
   r,i=ref(model,c,v);ident=i.get('identity',{});run=d['runs'].get(f'open_3d_{c}/{c}_{v}',{})
   row={'model':model,'case':c,'version':v,'legality':r['static_legality'],'wirelength_um':r['wirelength_dbu']/r['dbu_per_micron'],'overflow':r['overflow'],'potential':r['normalized_overflow_squared'],'rho':r['thermal_correlation'],'layers':r['by_layer'],'runtime':run.get('run',{}).get('runtime_seconds'),'rss_mib':(run.get('run',{}).get('peak_memory_bytes') or 0)/1048576,'guide_sha':run.get('guide_sha256_actual'),'identity':ident}
   rows.append(row)
   hash_ok=ident.get('guide_sha256')==run.get('guide_sha256_actual');checks.append({'key':key,'guide_sha_matches':hash_ok})
   if v in ['v3_5','v3_6','v4','v4_2']: identities.append((v,ident.get('input_sha256'),ident.get('reference_source_sha256'),ident.get('pin_assignment_policy')))
  if identities:
   checks.append({'group':model+'/'+c,'versions':[x[0] for x in identities],'same_input':all(x[1]==identities[0][1] for x in identities),'same_reference_source':all(x[2]==identities[0][2] for x in identities),'same_pin_assignment':all(x[3]==identities[0][3] for x in identities)})
platform=[]
for v,z in d['platform'].items():
 for c,p in z['scores']['cases'].items():
  raw=p['raw_report'];guide=z['zip_members'][c+'.output.guide'];local=d['runs'][c+'/'+c.replace('open_3d_','')+'_'+v]['guide_sha256_actual']
  assert guide==local
  platform.append({'v':v,'case':c.replace('open_3d_',''),'wl':raw['wirelength']['total_um'],'overflow':raw['congestion']['total_overflow'],'wl_score':raw['score']['wirelength_score'],'congestion_score':raw['score']['congestion_score'],'thermal_score':raw['score']['thermal_score'],'status':raw['status'],'guide_sha':guide})
payload={'rows':rows,'checks':checks,'platform':platform,'platform_totals':{v:{k:a['scores'][k] for k in ['total_score','wirelength_score','congestion_score','thermal_score']} for v,a in d['platform'].items()},'runs':d['runs']}
(out/'assets/chart_data.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding='utf8')
text=['# 数据来源与版本核对','', '核对日期：2026-11-04。只读取既有记录与 UI，未运行 Router 或评分器，未修改源码、配置、Guide 或历史报告。','', '## 1. 口径边界','', '| 口径 | 用途与限制 |','|---|---|','| 比赛平台返回报告 v1.4 | V3.5=45.39、V3.6=45.92；原始下载回执，不冒称 20261103 新官方算法 |','| OFFICIAL_OLD | 历史本地 ELF 兼容性成绩；不与平台或参考模型直接计算增益 |','| REFERENCE_20261029 | 自研统一参考模型，冻结来源；不是官方评分器 |','| REFERENCE_20261103 | 自研修订模型，Pin Track nearest_in_cell 为假设；不是新版官方 PASS |','| Router Local | 内部优化代理，不作为官方 Overflow |','', '平台原始报告明确标注线长为 guide-rectangle Manhattan MST proxy、拥塞为 GRT guide demand / merged DEF track capacity、DRC 为不可用（mock-DRT risk proxy）。平台 runtime_seconds=0 不作为实测运行时间。参考百分制分项、V4/V4.2 官方总分均为 N/A。','', '## 2. 平台提交与 Guide 身份','', '原始文件：`EDA/code_3DIC EDA/outputs/reports/official_platform/v3_5_24699/` 与 `v3_6_26152/` 内 `scores.json`、逐 Case `*_evaluation_report.json` 及 prediction ZIP。六份 ZIP Guide 与本地对应运行完整 SHA256 一致。','', '| Version | Case | 平台状态 | WL µm | Overflow | WL Score | Congestion Score | Thermal Score |','|---|---|---|---:|---:|---:|---:|---:|']
